"""Test helper generated by the export from tests.reference_cases."""

from __future__ import annotations


"""Recorded PVGIS data for Pisa and the engine reference cases.

The PVGIS files are public JRC data recorded on 2026-10-28 (see the ``source``
key in each file). No Google Solar data is recorded here: Google's terms
require cached Solar data to be refreshed within 30 days, so roof segments
in these cases are synthetic.
"""


import gzip
import json
from functools import lru_cache
from pathlib import Path

from kilowattchiaro_engine.models.solar_eval import PVGISMonthly, PVGISTMYResult

_FIXTURES = Path(__file__).parent / "fixtures" / "pvgis"

PISA_LAT = 43.72
PISA_LON = 10.40

# Ticket 311 reference case: 6 kWp + 10 kWh, 4,000 kWh/yr, Pisa.
REFERENCE_KWP = 6.0
REFERENCE_BATTERY_KWH = 10.0
REFERENCE_ANNUAL_KWH = 4000.0


@lru_cache(maxsize=1)
def pisa_tmy() -> PVGISTMYResult:
    with gzip.open(_FIXTURES / "pisa_tmy.json.gz", "rt") as f:
        return PVGISTMYResult.model_validate(json.load(f)["tmy"])


@lru_cache(maxsize=None)
def _pvcalc() -> dict:
    return json.loads((_FIXTURES / "pisa_pvcalc_1kwp_30deg.json").read_text())


def pisa_pvcalc_monthly(azimuth_pvgis: float, mounting: str = "free") -> list[float]:
    """PVcalc E_m (kWh per kWp) at 30 degrees; azimuth in the PVGIS convention."""
    key = int(azimuth_pvgis)
    key = 180 if key == -180 else key
    return list(_pvcalc()["mountingplace"][mounting][str(key)])


def pisa_monthly(azimuth_pvgis: float, kwp: float, mounting: str = "free") -> list[PVGISMonthly]:
    return [
        PVGISMonthly(month=i + 1, e_m=round(v * kwp, 1), h_m=0.0)
        for i, v in enumerate(pisa_pvcalc_monthly(azimuth_pvgis, mounting))
    ]
